            preferredSports?: ("SOCCER" | "BASKETBALL" | "FOOTBALL" | "BASEBALL" | "TENNIS" | "HOCKEY" | "GOLF" | "CRICKET" | "RUGBY" | "VOLLEYBALL" | "OTHER")[];
